"""CSV table loading helpers for minisql."""

import csv
import os
import re


_INTEGER = re.compile(r"-?[0-9]+\Z")
_DECIMAL = re.compile(r"(?:-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+)\Z")


def _convert(value):
    if value == "":
        return None
    if _INTEGER.fullmatch(value):
        return int(value)
    if _DECIMAL.fullmatch(value):
        return float(value)
    return value


def load_table(name, directory="."):
    """Load ``name.csv`` and return ``(column_names, tuple_rows)``.

    Values are converted according to the CSV rules in SPEC.md. All input
    errors are surfaced as QueryError so callers need only handle one public
    error type.
    """
    from . import QueryError

    path = os.path.join(os.fspath(directory), f"{name}.csv")
    try:
        with open(path, "r", encoding="utf-8-sig", newline="") as stream:
            reader = csv.reader(stream)
            try:
                header = next(reader)
            except StopIteration:
                raise QueryError(f"table {name!r} has no header")

            if not header or any(column == "" for column in header):
                raise QueryError(f"table {name!r} has an invalid header")
            folded = [column.casefold() for column in header]
            if len(set(folded)) != len(folded):
                raise QueryError(f"table {name!r} has duplicate column names")

            rows = []
            for line_number, fields in enumerate(reader, start=2):
                if len(fields) != len(header):
                    raise QueryError(
                        f"table {name!r} row {line_number} has {len(fields)} "
                        f"fields; expected {len(header)}"
                    )
                rows.append(tuple(_convert(field) for field in fields))
            return header, rows
    except QueryError:
        raise
    except (OSError, UnicodeError, csv.Error) as exc:
        raise QueryError(f"could not read table {name!r}: {exc}") from exc
